<?php
declare(strict_types=1);
namespace Nexus\Infrastructure\Persistence;
use Nexus\Domain\Administracion\AdministracionRepository;use Nexus\Domain\ValueObject\Cedula;
final class PdoAdministracionRepository implements AdministracionRepository
{
    private \PDO $pdo;private const C=['categoria_tecnologica'=>['CATEGORIA_TECNOLOGICA','id_categoria_tecnologica','esta_activa'],'categoria_prestamo'=>['CATEGORIA_PRESTAMO','id_categoria_prestamo','esta_activa'],'servicio_disponible'=>['SERVICIO_DISPONIBLE','id_servicio_disponible','esta_activo']];public function __construct(\PDO $p){$this->pdo=$p;}
    public function listarReportes():array{$q=$this->pdo->query("SELECT r.id_reporte_error id,r.tipo,r.contacto,r.asunto,r.detalle,r.estado,r.cedula_responsable responsableId,CONCAT(COALESCE(u.nombre,''),' ',COALESCE(u.apellido,'')) responsable,r.respuesta,r.fecha_creacion creadoEn,r.fecha_cierre cerradoEn FROM REPORTE_ERROR r LEFT JOIN USUARIO u ON u.cedula=r.cedula_responsable ORDER BY r.id_reporte_error DESC");return $q->fetchAll(\PDO::FETCH_ASSOC);}public function crearReporte(array $d):int{$q=$this->pdo->prepare('INSERT INTO REPORTE_ERROR(tipo,contacto,asunto,detalle) VALUES(?,?,?,?)');$q->execute([$d['tipo'],$d['contacto'],$d['asunto'],$d['detalle']]);return (int)$this->pdo->lastInsertId();}public function actualizarReporte(int $id,array $d,Cedula $r):bool{$q=$this->pdo->prepare("UPDATE REPORTE_ERROR SET estado=?,cedula_responsable=?,respuesta=?,fecha_cierre=CASE WHEN ? IN ('Resuelto','Rechazado') THEN NOW() ELSE NULL END WHERE id_reporte_error=?");$q->execute([$d['estado'],$r->value(),$d['respuesta'],$d['estado'],$id]);return $q->rowCount()===1;}
    public function listarCatalogo(string $t,bool $i):array{[$tabla,$id,$activo]=self::C[$t];$sql="SELECT $id id,nombre,descripcion,$activo activo FROM $tabla".($i?'':" WHERE $activo=1").' ORDER BY nombre';return $this->pdo->query($sql)->fetchAll(\PDO::FETCH_ASSOC);}public function crearCatalogo(string $t,string $n,string $d):int{[$tabla,,$activo]=self::C[$t];$q=$this->pdo->prepare("INSERT INTO $tabla(nombre,descripcion) VALUES(?,?) ON DUPLICATE KEY UPDATE descripcion=VALUES(descripcion),$activo=1");$q->execute([$n,$d]);return (int)$this->pdo->lastInsertId();}public function editarCatalogo(string $t,int $id,array $d):bool{[$tabla,$pk,$activo]=self::C[$t];$q=$this->pdo->prepare("UPDATE $tabla SET nombre=?,descripcion=?,$activo=? WHERE $pk=?");$q->execute([$d['nombre'],$d['descripcion'],$d['activo']?1:0,$id]);return $q->rowCount()===1;}public function bajaCatalogo(string $t,int $id):bool{[$tabla,$pk,$activo]=self::C[$t];$q=$this->pdo->prepare("UPDATE $tabla SET $activo=0 WHERE $pk=? AND $activo=1");$q->execute([$id]);return $q->rowCount()===1;}
    public function configuracion():array{return $this->pdo->query('SELECT clave,valor,descripcion,actualizado_en actualizadoEn,actualizado_por actualizadoPor FROM CONFIGURACION_SISTEMA ORDER BY clave')->fetchAll(\PDO::FETCH_ASSOC);}public function guardarConfiguracion(string $c,string $v,Cedula $u):void{$q=$this->pdo->prepare('INSERT INTO CONFIGURACION_SISTEMA(clave,valor,actualizado_por) VALUES(?,?,?) ON DUPLICATE KEY UPDATE valor=VALUES(valor),actualizado_por=VALUES(actualizado_por)');$q->execute([$c,$v,$u->value()]);}
    public function historial():array{$col=$this->pdo->query("SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='HISTORIAL_EQUIPO' AND COLUMN_NAME='descripcion'")->fetchColumn()?'h.descripcion':'NULL';$q=$this->pdo->query("SELECT h.id_historial_equipo id,h.fecha_registrado,CASE WHEN h.categoria='Traslado' THEN 'Traslado de equipo' ELSE h.categoria END etiqueta,$col descripcion,COALESCE(e.nombre_equipo,CONCAT('Equipo #',h.id_equipo)) referencia,'equipo' tipo FROM HISTORIAL_EQUIPO h LEFT JOIN EQUIPO e ON e.id_equipo=h.id_equipo UNION ALL SELECT h.id_historial_ubicacion id,h.fecha_registrado,'Ubicacion' etiqueta,h.descripcion,COALESCE(u.seccion_inventario,CONCAT('Ubicacion #',h.id_ubicacion)) referencia,'ubicacion' tipo FROM HISTORIAL_UBICACION h LEFT JOIN UBICACION u ON u.id_ubicacion=h.id_ubicacion ORDER BY fecha_registrado DESC");return $q->fetchAll(\PDO::FETCH_ASSOC);}
}
